#include <bits/stdc++.h>
#define second second
#define first first
#define fast_io ios::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr)
#define print(n) return cout << n, 0
#define set_prec(n) cout << fixed << setprecision(n)
#define push_back emplace_back
#define long long long
#define long_double long double
#pragma GCC optimize("Ofast,no-stack-protector,unroll-loops")
using namespace std;

const int MAXN = 1e6 + 100, INF = 1e9 + 7, MOD = 1e9 + 7, P = 6151, T = 2000, SQ = 280, lg = 64, lg2 = 34;
typedef pair<int, int> pii;

int n, d;
vector<int> v;

struct node {
    int dp[lg2][lg2], cnt[lg2][lg2];
    bool mark[lg2], tark[lg2];

    void merge(node &other) {
        for (int i = 0; i <= d; i++) {
            for (int j = 0; j <= d; j++) {
                cnt[i][j] = 0;
                for (int k = 0; k <= d; k++)
                    cnt[i][j] = (cnt[i][j] + dp[k][j] * other.dp[i][k]) % MOD;
            }
        }
        for (int i = 0; i < d; i++) {
            if (mark[i] && !other.mark[i]) {
                for (int j = 0; j <= d; j++)
                    cnt[i][j] = dp[i][j];
            }
            if (!mark[i] && other.mark[i]) {
                for (int j = 0; j <= d; j++)
                    cnt[j][i] = other.dp[j][i];
            }
            mark[i] |= other.mark[i];
        }
        for (int i = 0; i <= d; i++)
            for (int j = 0; j <= d; j++)
                dp[i][j] = cnt[i][j];
    }

    void clear() {
        for (int i = 0; i <= d; i++)
            for (int j = 0; j <= d; j++)
                dp[i][j] = cnt[i][j] = 0;
    }

    void shift(int x) {
        for (int i = 0; i <= d; i++)
            for (int j = 0; j <= d; j++)
                cnt[i][j] = 0;
        for (int i = 0; i < d; i++) {
            for (int j = 0; j < d; j++)
                cnt[(i + x) % d][(j + x) % d] = dp[i][j];
            cnt[(i + x) % d][d] = dp[i][d];
        }
        for (int i = 0; i < d; i++)
            cnt[d][(i + x) % d] = dp[d][i];
        cnt[d][d] = dp[d][d];

        for (int i = 0; i <= d; i++)
            for (int j = 0; j <= d; j++)
                dp[i][j] = cnt[i][j];

        for (int i = 0; i < d; i++)
            tark[i] = mark[(i + x) % d];
        for (int i = 0; i < d; i++)
            mark[i] = tark[i];
    }
} md[lg + 5], hp[lg + 5], ht;

node get_node(int x) {
    int h = x, pw = 1, t = -1;
    while (h >= d) {
        h /= d;
        pw *= d;
        t++;
    }
    x %= pw;
    if (t == -1)
        return hp[h];
    node ans = md[t];
    ht = md[t];
    for (int i = 1; i < h; i++) {
        ht.shift(1);
        ans.merge(ht);
    }
    ht = get_node(x);
    ht.shift(h);
    ans.merge(ht);
    return ans;
}

int main() {
    fast_io;
    cin >> n >> d;
    n--;
    int m = n;
    while (n) {
        v.push_back(n % d);
        n /= d;
    }
    hp[0].dp[d][d] = 2;
    hp[0].dp[d][0] = -1;
    hp[0].dp[0][d] = 1;
    hp[0].mark[0] = true;
    md[0] = hp[0];
    for (int i = 1; i < d; i++) {
        hp[i].dp[d][d] = 2;
        hp[i].dp[d][i] = -1;
        hp[i].dp[i][d] = 1;
        hp[i].mark[i] = true;
        md[0].merge(hp[i]);
        hp[i] = md[0];
    }
    for (int i = 1; i <= (int)v.size(); i++) {
        md[i] = md[i - 1];
        ht = md[i - 1];
        for (int j = 1; j < d; j++) {
            ht.shift(1);
            md[i].merge(ht);
        }
    }
    node ans = get_node(m);
    cout << ans.dp[d][d] << "\n";
    return 0;
}
